fn rule_block(yaml: &str, id: &str) -> (usize, usize) {
    let start = yaml.find(&format!("  - id: {id}\n")).unwrap();
    let end = yaml[start + 3..]
        .find("\n  - id: ")
        .map_or(yaml.len(), |e| start + 3 + e + 1);

